import{_ as a,c as r,o as t,ag as s}from"./chunks/framework.DQvKz0xt.js";const y=JSON.parse('{"title":"图层 (Layers) - Rive 编辑器","description":"图层 (Layers) 允许你在状态机中构建更复杂的逻辑和动画。 状态机上的一个图层一次只能播放一个动画。因此，如果你希望混合多个动画或向状态机添加额外的交互，可以创建多个图层。","frontmatter":{"title":"图层 (Layers) - Rive 编辑器","description":"图层 (Layers) 允许你在状态机中构建更复杂的逻辑和动画。 状态机上的一个图层一次只能播放一个动画。因此，如果你希望混合多个动画或向状态机添加额外的交互，可以创建多个图层。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 状态机, 图层"}]]},"headers":[],"relativePath":"editor/state-machine/layers.md","filePath":"editor/state-machine/layers.md","lastUpdated":1774838907000}'),n={name:"editor/state-machine/layers.md"};function i(o,e,p,l,d,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<p>状态机</p><h1 id="图层-layers" tabindex="-1">图层 (Layers) <a class="header-anchor" href="#图层-layers" aria-label="Permalink to &quot;图层 (Layers)&quot;">​</a></h1><p>图层 (Layers) 允许你在状态机中构建更复杂的逻辑和动画。</p><p>状态机上的一个图层一次只能播放一个动画。因此，如果你希望混合多个动画或向状态机添加额外的交互，可以创建多个图层。</p><p>例如，你可以使用图层来混合不同的背景动画，或者在单个画板上添加多个独立的交互逻辑。 <img src="https://help.rive.app/images/image_0.png" alt="多图层使用 Pn"></p><h3 id="​-创建新图层" tabindex="-1"><a href="#creating-a-new-layer">​</a> 创建新图层 <a class="header-anchor" href="#​-创建新图层" aria-label="Permalink to &quot;[​](#creating-a-new-layer) 创建新图层&quot;">​</a></h3><p>要创建新图层，请使用“图层 (Layers)”选项卡上的加号按钮。 每个新创建的图层都会自带一组默认状态（Entry, Any, Exit）。</p><h3 id="​-图层顺序" tabindex="-1"><a href="#layer-order">​</a> 图层顺序 <a class="header-anchor" href="#​-图层顺序" aria-label="Permalink to &quot;[​](#layer-order) 图层顺序&quot;">​</a></h3><p>图层的顺序非常重要：<strong>右侧的图层优先级高于左侧的图层</strong>。在大多数情况下这不影响使用，但如果你的多个图层中的状态控制了同一个对象的属性，那么最右侧图层中的动画将覆盖左侧图层的效果。</p><p><strong>更改图层顺序</strong> 你可以通过在“图层”选项卡上拖放图层来更改它们的顺序。</p><p><strong>删除图层</strong> 在图层名称上右键点击并选择“删除图层 (Delete Layer)”。</p><p><strong>重复图层</strong> 在图层名称上右键点击并选择“重复图层 (Duplicate Layer)”。</p><p><strong>禁用与启用图层</strong> 你可以通过右键菜单或点击图层旁的图标来禁用/启用特定图层，方便调试。</p><p><a href="/docs/editor/state-machine/listeners">监听器 (Listeners)</a><a href="https://help.rive.app/editor/events/overview" target="_blank" rel="noreferrer">事件概览 (Events Overview)</a></p>',14)])])}const _=a(n,[["render",i]]);export{y as __pageData,_ as default};
